import java.io.*;
import java.util.*;

public class Main {
    static boolean isVowel(char c) {
        return "aeiou".indexOf(c) >= 0;
    }

    public static void main(String[] args) throws IOException {
        String s = new String(System.in.readAllBytes()).trim();
        int n = s.length(), v = 0;
        for (char c : s.toCharArray()) if (isVowel(c)) v++;
        if (n % 2 != 0) {
            System.out.print("-1\n");
            return;
        }
        int target = n / 2, need = Math.abs(v - target);
        // Convert `need` characters of the larger class; each costs its distance to the other class.
        boolean fromVowels = v > target;
        int[] costs = new int[n];
        int m = 0;
        for (char c : s.toCharArray()) {
            if (isVowel(c) != fromVowels) continue;
            int best = Integer.MAX_VALUE;
            for (char to = 'a'; to <= 'z'; to++)
                if (isVowel(to) != fromVowels) best = Math.min(best, Math.abs(c - to));
            costs[m++] = best;
        }
        Arrays.sort(costs, 0, m);
        long total = 0;
        for (int i = 0; i < need; i++) total += costs[i];
        System.out.print(total + "\n");
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
	"strings"
)

func isVowel(c byte) bool { return strings.IndexByte("aeiou", c) >= 0 }

func main() {
	var s string
	fmt.Fscan(bufio.NewReader(os.Stdin), &s)
	n, v := len(s), 0
	for i := 0; i < n; i++ {
		if isVowel(s[i]) {
			v++
		}
	}
	if n%2 != 0 {
		fmt.Println(-1)
		return
	}
	target := n / 2
	need := v - target
	if need < 0 {
		need = -need
	}
	// Convert `need` characters of the larger class; each costs its distance to the other class.
	fromVowels := v > target
	costs := []int{}
	for i := 0; i < n; i++ {
		c := s[i]
		if isVowel(c) != fromVowels {
			continue
		}
		best := 1 << 30
		for to := byte('a'); to <= 'z'; to++ {
			if isVowel(to) != fromVowels {
				d := int(c) - int(to)
				if d < 0 {
					d = -d
				}
				best = min(best, d)
			}
		}
		costs = append(costs, best)
	}
	sort.Ints(costs)
	total := 0
	for i := 0; i < need; i++ {
		total += costs[i]
	}
	fmt.Println(total)
}
